// n8n node "ElCom queries" (W3). One query per year: this year and next. ElCom publishes next year's tariffs in early September.
// Canton means are the plain average of the municipal H4 totals, the same method the app uses today.
const year = new Date().getFullYear();
const query = (y) => `PREFIX elcom: <https://energy.ld.admin.ch/elcom/electricityprice/dimension/>
PREFIX schema: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?canton (AVG(?total) AS ?avg) (COUNT(?total) AS ?n) WHERE {
  GRAPH <https://lindas.admin.ch/elcom/electricityprice> {
    ?obs elcom:municipality ?muni ;
         elcom:category <https://energy.ld.admin.ch/elcom/electricityprice/category/H4> ;
         elcom:product <https://energy.ld.admin.ch/elcom/electricityprice/product/standard> ;
         elcom:period "${y}"^^xsd:gYear ;
         elcom:total ?total .
  }
  ?muni schema:containedInPlace ?canton .
  FILTER(STRSTARTS(STR(?canton), "https://ld.admin.ch/canton/"))
} GROUP BY ?canton`;
return [year, year + 1].map((y) => ({ json: { year: y, query: query(y) } }));

// n8n node "Parse ElCom" (W3). Keeps a value only if it is in a sane range. A failed or odd answer becomes an ok=false row.
// It never fills a gap with a guess; the app keeps reading the newest ok row (view bev_reference_latest).
const CANTONS = ['ZH','BE','LU','UR','SZ','OW','NW','GL','ZG','FR','SO','BS','BL','SH','AR','AI','SG','GR','AG','TG','TI','VD','VS','NE','GE','JU'];
const SOURCE = 'https://ld.admin.ch/query';
const asked = $('ElCom queries').all().map((i) => i.json.year);
const out = [];
$input.all().forEach((item, idx) => {
  const year = String(asked[idx] ?? '');
  const r = item.json;
  const bindings = r.statusCode === 200 && r.body && r.body.results && Array.isArray(r.body.results.bindings) ? r.body.results.bindings : null;
  if (!bindings || bindings.length === 0) {
    out.push({ kind: 'elcom.canton', key: 'all', period: year, value: null, unit: 'Rp/kWh', detail: null, publisher: 'ElCom', source_url: SOURCE, ok: false, note: `no answer for ${year} (status ${r.statusCode ?? 'none'})` });
    return;
  }
  for (const b of bindings) {
    const num = Number(String(b.canton && b.canton.value).split('/').pop());
    const code = CANTONS[num - 1];
    const avg = Number(b.avg && b.avg.value);
    const n = Number(b.n && b.n.value);
    const good = code && Number.isFinite(avg) && avg >= 10 && avg <= 80 && n >= 1;
    out.push({
      kind: 'elcom.canton', key: code || `bfs-${num}`, period: year,
      value: good ? Math.round(avg * 100) / 100 : null, unit: 'Rp/kWh', detail: null,
      publisher: 'ElCom', source_url: SOURCE, ok: Boolean(good),
      note: good ? `mean of ${n} municipal H4 totals` : `rejected: avg ${b.avg && b.avg.value}, n ${b.n && b.n.value}`,
    });
  }
});
return [{ json: { rows: out } }];

// n8n node "Parse BFE" (W3). Counts public charging points (EVSE ids) per Swiss postcode from the BFE open data.
// The file has addresses of charging points, not of people. Only counts per postcode are kept. Open data, attribution: BFE.
const SOURCE = 'https://data.geo.admin.ch/ch.bfe.ladestellen-elektromobilitaet/data/oicp/ch.bfe.ladestellen-elektromobilitaet.json';
const r = $input.first().json;
const day = new Date().toISOString().slice(0, 10);
const fail = (why) => [{ json: { rows: [{ kind: 'charging.plz', key: 'all', period: day, value: null, unit: 'EVSE', detail: null, publisher: 'BFE', source_url: SOURCE, ok: false, note: why }] } }];
const body = r.body;
const groups = body && Array.isArray(body.EVSEData) ? body.EVSEData : null;
if (r.statusCode !== 200 || !groups) return fail(`no usable file (status ${r.statusCode ?? 'none'})`);
const seen = new Set();
const byPlz = {};
let total = 0;
for (const g of groups) {
  const records = Array.isArray(g.EVSEDataRecord) ? g.EVSEDataRecord : [g];
  for (const rec of records) {
    const id = rec && rec.EvseID;
    const plz = rec && rec.Address && String(rec.Address.PostalCode || '').trim();
    if (!id || seen.has(id) || !/^\d{4}$/.test(plz || '')) continue;
    seen.add(id);
    const fast = (Array.isArray(rec.ChargingFacilities) ? rec.ChargingFacilities : []).some((f) => Number(f.power) >= 50);
    const cell = (byPlz[plz] ??= [0, 0]);
    cell[0] += 1;
    if (fast) cell[1] += 1;
    total += 1;
  }
}
if (total < 1000) return fail(`only ${total} charging points parsed; the file layout may have changed`);
return [{ json: { rows: [{ kind: 'charging.plz', key: 'all', period: day, value: total, unit: 'EVSE', detail: JSON.stringify(byPlz), publisher: 'BFE', source_url: SOURCE, ok: true, note: 'detail: {postcode: [charging points, of which 50 kW or more]}' }] } }];

// n8n node "BFS file URL" (W3). Paste the CURRENT XLSX address of the BFS table here, between the quotes.
// While it is empty, this branch stops here and nothing is fetched.
const url = '';
if (!url) return [];
return [{ json: { url } }];

// n8n node "Parse BFS" (W3). BFS publishes "LIK, Durchschnittspreise fuer Energie und Treibstoffe" as XLSX.
// The layout was NOT confirmed when this was written. So it looks for the two rows by their label and the period by its header,
// and gives up (ok=false) when it cannot find all three. Look at this node's output on the first run before switching on the insert.
const SOURCE = $('BFS file URL').first().json.url || 'https://www.bfs.admin.ch/';
const rowsIn = $input.all().map((i) => Object.values(i.json));
const fail = (why) => [{ json: { rows: [{ kind: 'pump', key: 'all', period: 'unknown', value: null, unit: 'CHF/l', detail: null, publisher: 'BFS', source_url: SOURCE, ok: false, note: why }] } }];
if (!rowsIn.length) return fail('no rows read; the file URL is probably empty or old');
const periodOf = (cell) => {
  const s = String(cell ?? '').trim();
  let m = s.match(/^(\d{4})[-/ ]?(\d{2})$/); if (m) return `${m[1]}-${m[2]}`;
  m = s.match(/^(\d{1,2})\.(\d{4})$/); if (m) return `${m[2]}-${m[1].padStart(2, '0')}`;
  return null;
};
const find = (label) => rowsIn.find((r) => r.some((c) => typeof c === 'string' && label.test(c)));
const lastNumber = (row) => { for (let i = row.length - 1; i >= 0; i--) { const n = Number(String(row[i]).replace(',', '.')); if (Number.isFinite(n) && n > 0.5 && n < 5) return { n, col: i }; } return null; };
const header = rowsIn.find((r) => r.filter((c) => periodOf(c)).length >= 3);
const out = [];
for (const [key, label] of [['unleaded95', /(bleifrei|unleaded|sans plomb).*95|^benzin/i], ['diesel', /diesel/i]]) {
  const row = find(label);
  const hit = row && lastNumber(row);
  const period = hit && header ? periodOf(header[hit.col]) : null;
  out.push(hit && period
    ? { kind: 'pump', key, period, value: Math.round(hit.n * 1000) / 1000, unit: 'CHF/l', detail: null, publisher: 'BFS', source_url: SOURCE, ok: true, note: 'last monthly value in the row; check against the BFS table' }
    : { kind: 'pump', key, period: period || 'unknown', value: null, unit: 'CHF/l', detail: null, publisher: 'BFS', source_url: SOURCE, ok: false, note: `could not read ${key}: ${!row ? 'label not found' : !hit ? 'no price in the row' : 'no period header found'}` });
}
return [{ json: { rows: out } }];
